import{_ as t,o as h,c as g,a2 as i}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Chi tiết Hệ thống Vòng tròn Sự sống","description":"","frontmatter":{},"headers":[],"relativePath":"vi/12-生命循环体系详解.md","filePath":"vi/12-生命循环体系详解.md"}'),c={name:"vi/12-生命循环体系详解.md"};function a(l,n,u,r,o,s){return h(),g("div",null,[...n[0]||(n[0]=[i('<h1 id="chi-tiet-he-thong-vong-tron-su-song" tabindex="-1">Chi tiết Hệ thống Vòng tròn Sự sống <a class="header-anchor" href="#chi-tiet-he-thong-vong-tron-su-song" aria-label="Permalink to &quot;Chi tiết Hệ thống Vòng tròn Sự sống&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Số tài liệu</td><td>12</td></tr><tr><td>Mô-đun</td><td>Quy luật Vũ trụ và Hệ thống Tu luyện</td></tr><tr><td>Từ khóa chính</td><td>Vòng tròn Sự sống, Trao đổi Năng lượng, Sự sống Liên tục, Cộng sinh Sinh thái, Ba Cơ sở Nguyên bản</td></tr></tbody></table><h2 id="_1-tong-quan-he-thong" tabindex="-1">1. Tổng quan Hệ thống <a class="header-anchor" href="#_1-tong-quan-he-thong" aria-label="Permalink to &quot;1. Tổng quan Hệ thống&quot;">​</a></h2><p>Hệ thống Vòng tròn Sự sống là hệ thống thứ hai trong ba trăm hệ thống tu luyện nguyên bản, đứng thứ hai trong &quot;Ba Cơ sở Nguyên bản&quot;, và là nền tảng của tất cả các hệ thống tu luyện lấy năng lượng sự sống làm cốt lõi. Hệ thống này lấy &quot;vòng tròn lành mạnh của năng lượng sự sống&quot; làm nguyên lý cốt lõi, và nhấn mạnh rằng việc trao đổi năng lượng giữa bản thân tu luyện giả với môi trường, cũng như giữa tu luyện giả với các sự sống khác, phải là dạng vòng tròn, cùng có lợi, chứ không phải dạng cướp bóc, một chiều. Hệ thống Vòng tròn Sự sống không chỉ nâng cao sức sống và cảnh giới của cá nhân, mà còn có thể cải thiện môi trường sinh thái nơi tu luyện giả sinh sống, thực hiện hiệu ứng cộng sinh của &quot;tu luyện một người, mang lại lợi ích cho một vùng&quot;.</p><p>Hệ thống Vòng tròn Sự sống phù hợp cho sự sống của tất cả các chủng tộc, đặc biệt là các tu luyện giả có thể chất nhạy cảm, có ái lực mạnh với thiên nhiên, và coi trọng chất lượng cuộc sống cũng như sự trường thọ. Hệ thống này là một trong những hệ thống có phạm vi ứng dụng rộng rãi nhất và gắn liền chặt chẽ nhất với cuộc sống hàng ngày trong ba trăm hệ thống, và được gọi là &quot;hệ thống nguyên bản gần gũi với đất đai nhất&quot;.</p><h2 id="_2-nguyen-ly-cot-loi-he-thong" tabindex="-1">2. Nguyên lý Cốt lõi Hệ thống <a class="header-anchor" href="#_2-nguyen-ly-cot-loi-he-thong" aria-label="Permalink to &quot;2. Nguyên lý Cốt lõi Hệ thống&quot;">​</a></h2><p>Nguyên lý cốt lõi của Hệ thống Vòng tròn Sự sống là &quot;bảo tồn và gia tăng vòng tròn năng lượng sự sống&quot;, có thể được hiểu từ ba cấp độ sau:</p><h3 id="_2-1-vong-tron-noi-bo-ca-nhan" tabindex="-1">2.1 Vòng tròn nội bộ cá nhân <a class="header-anchor" href="#_2-1-vong-tron-noi-bo-ca-nhan" aria-label="Permalink to &quot;2.1 Vòng tròn nội bộ cá nhân&quot;">​</a></h3><p>Vòng tròn nội bộ cá nhân đề cập đến vòng tròn năng lượng sự sống bên trong bản thân tu luyện giả. Năng lượng sự sống lưu thông theo các đường kinh lạc, tạng phủ, điền điền, và ý thức của tu luyện giả theo các lộ trình cụ thể, và mỗi vòng tròn làm cho năng lượng được tinh khiết hóa và tăng cường. Chất lượng của vòng tròn nội bộ cá nhân quyết định sức sống cơ bản, khả năng phục hồi, và khả năng chống hao mòn của tu luyện giả.</p><p>Khác với tu luyện kiểu cướp bóc, vòng tròn nội bộ của Hệ thống Vòng tròn Sự sống không theo đuổi &quot;năng lượng càng nhiều càng tốt&quot;, mà theo đuổi &quot;vòng tròn càng thông suốt càng tốt&quot;. Việc tích lũy năng lượng phải dựa trên sự thông suốt của vòng tròn, nếu không, năng lượng dư thừa thay vào đó sẽ gây ra tắc nghẽn và phản ứng ngược.</p><h3 id="_2-2-vong-tron-ben-ngoai-giua-ca-nhan-va-moi-truong" tabindex="-1">2.2 Vòng tròn bên ngoài giữa cá nhân và môi trường <a class="header-anchor" href="#_2-2-vong-tron-ben-ngoai-giua-ca-nhan-va-moi-truong" aria-label="Permalink to &quot;2.2 Vòng tròn bên ngoài giữa cá nhân và môi trường&quot;">​</a></h3><p>Vòng tròn bên ngoài đề cập đến việc trao đổi năng lượng sự sống giữa tu luyện giả và môi trường xung quanh. Tu luyện giả hấp thụ năng lượng sự sống từ môi trường (như linh khí trời đất, tinh khí thực vật, năng lượng khoáng chất, v.v.), và đồng thời giải phóng năng lượng sự sống đã được tinh khiết hóa bởi bản thân ra môi trường (như trường năng lượng sự sống, năng lượng thanh lọc, năng lượng thúc đẩy tăng trưởng, v.v.). Sự trao đổi này là hai chiều, cùng có lợi: tu luyện giả nhận được năng lượng cần thiết cho tu luyện, môi trường nhận được sự thanh lọc và nuôi dưỡng.</p><p>Chìa khóa của vòng tròn bên ngoài nằm ở &quot;cân bằng thu chi và có thặng dư&quot;. Năng lượng mà tu luyện giả hấp thụ không được vượt quá khả năng cung cấp của môi trường, và năng lượng giải phóng phải có lợi cho môi trường. Khi vòng tròn bên ngoài hoạt động tốt, môi trường xung quanh tu luyện giả ngày càng trở nên dễ sinh sống, hệ sinh thái ngày càng thịnh vượng, hình thành vòng tròn lành mạnh của &quot;người nuôi đất, đất nuôi người&quot;.</p><h3 id="_2-3-vong-tron-cong-sinh-giua-cac-ca-nhan" tabindex="-1">2.3 Vòng tròn cộng sinh giữa các cá nhân <a class="header-anchor" href="#_2-3-vong-tron-cong-sinh-giua-cac-ca-nhan" aria-label="Permalink to &quot;2.3 Vòng tròn cộng sinh giữa các cá nhân&quot;">​</a></h3><p>Vòng tròn cộng sinh đề cập đến việc trao đổi năng lượng sự sống cùng có lợi giữa tu luyện giả và các sự sống khác (bao gồm các tu luyện giả khác, sự sống thông thường, động thực vật, v.v.). Các hình thức của vòng tròn cộng sinh bao gồm: sự truyền thừa và phản hồi năng lượng giữa sư phụ và đệ tử, sự bổ sung năng lượng sự sống giữa các bạn tình, việc chia sẻ năng lượng giữa tu luyện giả và sự sống hợp đồng, sự cộng hưởng năng lượng tập thể giữa các tu luyện giả trong cộng đồng, v.v.</p><p>Nguyên tắc cốt lõi của vòng tròn cộng sinh là &quot;cùng có lợi, tự nguyện bình đẳng&quot;. Bất kỳ bên nào cũng không được lấy năng lượng bằng cái giá phải trả cho sự tổn thương của bên kia, và sự trao đổi phải được cả hai bên tự nguyện thực hiện và cả hai đều có thể hưởng lợi từ đó. Vòng tròn cộng sinh có thể tạo ra hiệu ứng hiệp đồng &quot;1+1&gt;2&quot;, làm cho tất cả các sự sống tham gia vào vòng tròn đều đạt được tiến bộ nhanh hơn so với tu luyện một mình.</p><h2 id="_3-phan-chia-canh-gioi-va-đac-điem-moi-giai-đoan" tabindex="-1">3. Phân chia Cảnh giới và Đặc điểm Mỗi Giai đoạn <a class="header-anchor" href="#_3-phan-chia-canh-gioi-va-đac-điem-moi-giai-đoan" aria-label="Permalink to &quot;3. Phân chia Cảnh giới và Đặc điểm Mỗi Giai đoạn&quot;">​</a></h2><p>Hệ thống Vòng tròn Sự sống được chia thành năm cảnh giới cốt lõi:</p><table tabindex="0"><thead><tr><th>Cảnh giới</th><th>Tên</th><th>Đặc điểm Cốt lõi</th><th>Mức Năng lượng Sự sống</th><th>Khả năng Đặc trưng</th></tr></thead><tbody><tr><td>Cảnh giới thứ nhất</td><td>Cảm sinh</td><td>Nhận thức ban đầu về sự tồn tại và dòng chảy của năng lượng sự sống, có khả năng thực hiện vòng tròn nội bộ cơ bản</td><td>Sức sống tăng 10%-30%</td><td>Nhận thức sự sống: có thể nhận thức trạng thái năng lượng của bản thân và các sự sống xung quanh</td></tr><tr><td>Cảnh giới thứ hai</td><td>Vòng tròn</td><td>Vòng tròn nội bộ thông suốt và ổn định, bắt đầu thiết lập vòng tròn bên ngoài với môi trường</td><td>Sức sống tăng 30%-100%</td><td>Hấp thụ và giải phóng năng lượng: có thể chủ động hấp thụ năng lượng sự sống từ môi trường và giải phóng ra môi trường</td></tr><tr><td>Cảnh giới thứ ba</td><td>Sinh sinh</td><td>Vòng tròn bên ngoài hoạt động lành mạnh, môi trường xung quanh bắt đầu có sự cải thiện sinh thái</td><td>Sức sống tăng 100%-300%</td><td>Sự sống liên tục: trường năng lượng sự sống liên tục nuôi dưỡng các sự sống xung quanh, thúc đẩy tăng trưởng thực vật và phục hồi sinh thái</td></tr><tr><td>Cảnh giới thứ tư</td><td>Hóa sinh</td><td>Năng lượng sự sống được tinh khiết hóa cao độ, có khả năng tinh chỉnh và biến đổi hình thái sự sống</td><td>Sức sống tăng 300%-1000%</td><td>Hóa sinh sự sống: có thể tăng tốc lành vết thương, sửa chữa tổn thương cơ quan, kéo dài tuổi thọ</td></tr><tr><td>Cảnh giới thứ năm</td><td>Nguyên sinh</td><td>Chạm đến quy luật nguyên bản của sự sống, có khả năng tạo ra hình thái sự sống mới và hệ sinh thái</td><td>Sức sống tăng hơn 1000%</td><td>Tạo sinh nguyên bản: có thể tạo ra hệ sinh thái vi mô trong không gian cách ly, thiết kế hình thái sự sống mới</td></tr></tbody></table><p>Việc đột phá mỗi cảnh giới đều phải thông qua &quot;đánh giá vòng tròn sự sống&quot;: đánh giá chất lượng vòng tròn nội bộ của tu luyện giả, lợi ích sinh thái của vòng tròn bên ngoài, và mức độ cùng có lợi của vòng tròn cộng sinh, chỉ khi cả ba mục đều đạt tiêu chuẩn thì việc nâng cao cảnh giới mới có thể được xác nhận.</p><h2 id="_4-phuong-phap-tu-luyen-cot-loi-he-thong" tabindex="-1">4. Phương pháp Tu luyện Cốt lõi Hệ thống <a class="header-anchor" href="#_4-phuong-phap-tu-luyen-cot-loi-he-thong" aria-label="Permalink to &quot;4. Phương pháp Tu luyện Cốt lõi Hệ thống&quot;">​</a></h2><h3 id="_4-1-phuong-phap-tu-luyen-vong-tron-noi-bo" tabindex="-1">4.1 Phương pháp Tu luyện Vòng tròn Nội bộ <a class="header-anchor" href="#_4-1-phuong-phap-tu-luyen-vong-tron-noi-bo" aria-label="Permalink to &quot;4.1 Phương pháp Tu luyện Vòng tròn Nội bộ&quot;">​</a></h3><p>Tu luyện vòng tròn nội bộ là nền tảng của Hệ thống Vòng tròn Sự sống, và bao gồm:</p><ul><li><strong>Phương pháp thông kinh lạc</strong>: thông qua hơi thở cụ thể và hướng dẫn ý thức, thông suốt kinh lạc toàn thân, đảm bảo sự thông suốt của đường dẫn vòng tròn năng lượng sự sống</li><li><strong>Phương pháp điều hòa tạng phủ</strong>: điều chỉnh sự cân bằng năng lượng của ngũ tạng lục phủ, làm cho việc trao đổi năng lượng giữa các cơ quan trở nên phối hợp và có trật tự</li><li><strong>Phương pháp nuôi dưỡng điền điền</strong>: nuôi dưỡng hạt giống sự sống - lõi của năng lượng sự sống trong điền điền; hạt giống sự sống càng mạnh, động lực của vòng tròn năng lượng sự sống càng đủ</li><li><strong>Phương pháp vòng tròn chu thiên</strong>: hướng dẫn năng lượng sự sống lưu thông theo lộ trình của tiểu chu thiên và đại chu thiên, mỗi vòng tròn hoàn chỉnh làm năng lượng tinh khiết thêm một phần</li></ul><h3 id="_4-2-phuong-phap-tu-luyen-vong-tron-ben-ngoai" tabindex="-1">4.2 Phương pháp Tu luyện Vòng tròn Bên ngoài <a class="header-anchor" href="#_4-2-phuong-phap-tu-luyen-vong-tron-ben-ngoai" aria-label="Permalink to &quot;4.2 Phương pháp Tu luyện Vòng tròn Bên ngoài&quot;">​</a></h3><p>Tu luyện vòng tròn bên ngoài là đặc trưng của Hệ thống Vòng tròn Sự sống, và bao gồm:</p><ul><li><strong>Phương pháp hấp thụ và giải phóng linh khí</strong>: hấp thụ linh khí trời đất từ môi trường, sau khi được tinh khiết hóa bởi bản thân thì giải phóng trở lại môi trường, hình thành vòng tròn thanh lọc</li><li><strong>Phương pháp cộng sinh với thực vật</strong>: thiết lập kết nối năng lượng với thực vật, thu được tinh khí từ thực vật, đồng thời gửi năng lượng thúc đẩy tăng trưởng đến thực vật</li><li><strong>Phương pháp giao tiếp địa mạch</strong>: thiết lập kết nối với năng lượng địa mạch của hành tinh, tham gia vào vòng tròn năng lượng sự sống cấp độ hành tinh</li><li><strong>Phương pháp phục hồi sinh thái</strong>: tiêm trường năng lượng sự sống của bản thân vào môi trường sinh thái bị tổn thương, tăng tốc phục hồi sinh thái và phục hồi loài</li></ul><h3 id="_4-3-phuong-phap-tu-luyen-vong-tron-cong-sinh" tabindex="-1">4.3 Phương pháp Tu luyện Vòng tròn Cộng sinh <a class="header-anchor" href="#_4-3-phuong-phap-tu-luyen-vong-tron-cong-sinh" aria-label="Permalink to &quot;4.3 Phương pháp Tu luyện Vòng tròn Cộng sinh&quot;">​</a></h3><p>Tu luyện vòng tròn cộng sinh là nội dung cấp cao của Hệ thống Vòng tròn Sự sống, và bao gồm:</p><ul><li><strong>Phương pháp truyền thừa sư đệ tử</strong>: sư phụ truyền cho đệ tử năng lượng sự sống đã được tinh khiết hóa và kinh nghiệm tu luyện, tiến bộ tu luyện của đệ tử phản hồi lại sư phụ, hình thành vòng tròn dạy và học cùng tiến bộ</li><li><strong>Phương pháp song tu bạn tình</strong>: dựa trên kết nối cảm xúc sâu sắc, các bạn tình thực hiện sự bổ sung và cộng hưởng năng lượng sự sống, thực hiện sự nâng cao chung</li><li><strong>Phương pháp cộng hưởng tập thể</strong>: nhiều tu luyện giả đồng thời thực hiện tu luyện vòng tròn sự sống, các vòng tròn năng lượng cá nhân cộng hưởng với nhau, tạo ra trường năng lượng tập thể</li><li><strong>Phương pháp cộng sinh hợp đồng</strong>: thiết lập hợp đồng cộng sinh bình đẳng với các sự sống khác (như linh thú, tinh linh, v.v.), chia sẻ năng lượng sự sống và thành quả tu luyện</li></ul><h2 id="_5-loi-ich-sinh-thai-va-gia-tri-xa-hoi-cua-he-thong" tabindex="-1">5. Lợi ích Sinh thái và Giá trị Xã hội của Hệ thống <a class="header-anchor" href="#_5-loi-ich-sinh-thai-va-gia-tri-xa-hoi-cua-he-thong" aria-label="Permalink to &quot;5. Lợi ích Sinh thái và Giá trị Xã hội của Hệ thống&quot;">​</a></h2><p>Giá trị độc đáo của Hệ thống Vòng tròn Sự sống nằm ở chỗ nó không chỉ nâng cao cảnh giới của tu luyện giả cá nhân, mà còn tạo ra lợi ích sinh thái và giá trị xã hội đáng kể:</p><h3 id="_5-1-loi-ich-sinh-thai" tabindex="-1">5.1 Lợi ích Sinh thái <a class="header-anchor" href="#_5-1-loi-ich-sinh-thai" aria-label="Permalink to &quot;5.1 Lợi ích Sinh thái&quot;">​</a></h3><ul><li><strong>Thanh lọc môi trường</strong>: trường năng lượng sự sống của tu luyện giả có thể thanh lọc các chất có hại trong không khí, nguồn nước, và đất đai</li><li><strong>Phục hồi sinh thái</strong>: tu luyện giả cấp cao có thể tăng tốc phục hồi hệ sinh thái bị tổn thương, thúc đẩy sinh sản của các loài có nguy cơ tuyệt chủng</li><li><strong>Điều tiết khí hậu</strong>: các trường tu luyện vòng tròn sự sống quy mô lớn có thể điều tiết khí hậu địa phương, tăng lượng mưa, điều tiết nhiệt độ</li><li><strong>Cải tạo đất đai</strong>: đất đai xung quanh tu luyện giả trở nên màu mỡ hơn, có lợi cho nông nghiệp và tăng trưởng thực vật</li></ul><h3 id="_5-2-gia-tri-xa-hoi" tabindex="-1">5.2 Giá trị Xã hội <a class="header-anchor" href="#_5-2-gia-tri-xa-hoi" aria-label="Permalink to &quot;5.2 Giá trị Xã hội&quot;">​</a></h3><ul><li><strong>Giá trị y tế</strong>: tu luyện giả của Hệ thống Vòng tròn Sự sống là những người chữa bệnh tự nhiên, có thể cung cấp dịch vụ y tế cơ bản cho cộng đồng</li><li><strong>Giá trị nông nghiệp</strong>: trường năng lượng sự sống của tu luyện giả có thể nâng cao đáng kể sản lượng và chất lượng nông sản</li><li><strong>Giá trị trường thọ</strong>: tu luyện giả của hệ thống này thường có tuổi thọ dài, có thể tích lũy nhiều kinh nghiệm và trí tuệ hơn cho văn minh</li><li><strong>Giá trị hòa hợp</strong>: phương pháp tu luyện vòng tròn cộng sinh thúc đẩy mối quan hệ hòa hợp giữa người với người, giữa người với thiên nhiên</li></ul><h2 id="_6-uu-điem-va-han-che-cua-he-thong" tabindex="-1">6. Ưu điểm và Hạn chế của Hệ thống <a class="header-anchor" href="#_6-uu-điem-va-han-che-cua-he-thong" aria-label="Permalink to &quot;6. Ưu điểm và Hạn chế của Hệ thống&quot;">​</a></h2><h3 id="_6-1-uu-điem" tabindex="-1">6.1 Ưu điểm <a class="header-anchor" href="#_6-1-uu-điem" aria-label="Permalink to &quot;6.1 Ưu điểm&quot;">​</a></h3><ul><li>Phạm vi ứng dụng rộng, hầu như tất cả các chủng tộc đều có thể tu luyện</li><li>Quá trình tu luyện ôn hòa và an toàn, rủi ro tu luyện lệch lạc cực kỳ thấp</li><li>Lợi ích sinh thái đáng kể, được văn minh và cộng đồng đánh giá cao</li><li>Hiệu quả kéo dài tuổi thọ rõ rệt, là lựa chọn hàng đầu của các tu luyện giả theo đuổi sự trường thọ</li><li>Gắn liền chặt chẽ với cuộc sống hàng ngày, không cần môi trường tu luyện đặc biệt</li></ul><h3 id="_6-2-han-che" tabindex="-1">6.2 Hạn chế <a class="header-anchor" href="#_6-2-han-che" aria-label="Permalink to &quot;6.2 Hạn chế&quot;">​</a></h3><ul><li>Việc nâng cao sức chiến đấu ở giai đoạn đầu tương đối chậm, không phù hợp với các tu luyện giả theo đuổi sức chiến đấu nhanh chóng</li><li>Có sự phụ thuộc nhất định vào môi trường, hiệu quả tu luyện bị hạn chế ở các khu vực cực kỳ thiếu năng lượng sự sống</li><li>Việc đột phá cảnh giới cấp cao đòi hỏi sự thấu hiểu sâu sắc về nguyên bản sự sống, có yêu cầu cao về tính cách</li><li>Vòng tròn cộng sinh cần tìm thấy đối tác phù hợp, hiệu quả của việc tu luyện một mình bị hạn chế</li></ul><h2 id="_7-tuong-thich-voi-cac-he-thong-khac" tabindex="-1">7. Tương thích với Các Hệ thống Khác <a class="header-anchor" href="#_7-tuong-thich-voi-cac-he-thong-khac" aria-label="Permalink to &quot;7. Tương thích với Các Hệ thống Khác&quot;">​</a></h2><p>Hệ thống Vòng tròn Sự sống có sự tương thích tốt với các hệ thống khác, đặc biệt là:</p><ul><li>Tu luyện kết hợp với Hệ thống Lặp lại Suy diễn: có thể suy diễn lộ trình tối ưu của vòng tròn năng lượng sự sống, đẩy nhanh sự tinh khiết hóa của vòng tròn nội bộ</li><li>Tu luyện kết hợp với Hệ thống Điều phối Pháp lý Không gian: có thể xây dựng không gian vòng tròn năng lượng sự sống chuyên dụng, nâng cao hiệu quả tu luyện</li><li>Tu luyện kết hợp với các hệ thống loại Nâng cao Ý thức: sự tinh khiết hóa của năng lượng sự sống giúp ổn định và nâng cao ý thức</li><li>Tu luyện kết hợp với các hệ thống loại Kỹ thuật Ứng dụng: công nghệ vòng tròn sự sống là nền tảng cốt lõi của kỹ thuật sinh thái, kỹ thuật y tế</li></ul><h2 id="loi-ket" tabindex="-1">Lời kết <a class="header-anchor" href="#loi-ket" aria-label="Permalink to &quot;Lời kết&quot;">​</a></h2><p>Hệ thống Vòng tròn Sự sống là sự thể hiện trực tiếp nhất của khái niệm &quot;cộng sinh&quot; của Văn minh Cộng sinh Neo trong lĩnh vực tu luyện. Nó lấy vòng tròn lành mạnh của năng lượng sự sống làm cốt lõi, kết hợp chặt chẽ việc tu luyện cá nhân với cải thiện sinh thái và hòa hợp xã hội, chứng minh rằng sự tiến hóa không cần phải đạt được bằng cái giá phải trả cho môi trường hoặc người khác. Mục tiêu cuối cùng của Hệ thống Vòng tròn Sự sống là làm cho mỗi tu luyện giả trở thành người bảo vệ và người nuôi dưỡng sự sống, đồng thời nâng cao cảnh giới của bản thân, làm cho thế giới xung quanh trở nên đẹp đẽ hơn.</p><h2 id="tai-lieu-lien-quan" tabindex="-1">Tài liệu liên quan <a class="header-anchor" href="#tai-lieu-lien-quan" aria-label="Permalink to &quot;Tài liệu liên quan&quot;">​</a></h2><ul><li>10-三百套本源修炼体系总览 (Tổng quan Ba trăm Hệ thống Tu luyện Nguyên bản)</li><li>15-能量循环与转化法则 (Quy luật Vòng tròn và Biến đổi Năng lượng)</li><li>38-共生医疗体系 (Hệ thống Y tế Cộng sinh)</li></ul>',48)])])}const v=t(c,[["render",a]]);export{p as __pageData,v as default};
